{% block title %}Inscription{% endblock %}

{% block body %}
    <div class=\"row justify-content-center\">
        <div class=\"col-md-8\">
            <h1 class=\"h3 mb-3 font-weight-normal text-center\">Créer un compte</h1>

            {{ form_errors(registrationForm) }}

            {{ form_start(registrationForm) }}
                <div class=\"row\">
                    <div class=\"col-md-6 mb-3\">
                        {{ form_row(registrationForm.prenom) }}
                    </div>
                    <div class=\"col-md-6 mb-3\">
                        {{ form_row(registrationForm.nom) }}
                    </div>
                </div>
                
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.email) }}
                </div>
                
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.adresse) }}
                </div>
                
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.telephone) }}
                </div>

                <div class=\"mb-3\">
                    {{ form_row(registrationForm.plainPassword, {
                        label: 'Mot de passe'
                    }) }}
                </div>
                
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.agreeTerms, {
                        label: 'J\\'accepte les conditions d\\'utilisation'
                    }) }}
                </div>

                <button type=\"submit\" class=\"btn btn-primary btn-lg w-100\">S'inscrire</button>
                
                <div class=\"mt-3 text-center\">
                    Déjà un compte ? <a href=\"{{ path('app_login') }}\">Connectez-vous ici</a>
                </div>
            {{ form_end(registrationForm) }}
        </div>
    </div>
{% endblock %}
